PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'ARTICLE',
  '37045140',
  'Golfetti IF, Noll FB',
  'After more than half a century: Dielis diabo (Hymenoptera: Scoliidae: Scoliinae), a new scoliid from the Neotropics.',
  'Zootaxa',
  '2023 Jan 31',
  'https://doi.org/10.11646/zootaxa.5231.3.10',
  1,
  1,
  'Revision reason: Other reason (specify in notes)
Prova rao',
  1,
  'Prova1',
  'Staphylococcus aureus subsp. aureus COL'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='37045140'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Golfetti IF, Noll FB' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'After more than half a century: Dielis diabo (Hymenoptera: Scoliidae: Scoliinae), a new scoliid from the Neotropics.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Zootaxa' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2023 Jan 31' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.11646/zootaxa.5231.3.10' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'Prova1' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Staphylococcus aureus subsp. aureus COL' ELSE reported_species END,
  contains_promoter_data = 1,
  contains_expression_data = 1,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'Revision reason: Other reason (specify in notes)
Prova rao'
    ELSE submission_notes
  END
WHERE pmid='37045140';

INSERT INTO core_tf (name, family_id, description)
SELECT 'Prova1', 13, 'Prova descripcio'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('Prova1')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 13),
  description = CASE WHEN description IS NULL THEN 'Prova descripcio' ELSE description END
WHERE lower(name)=lower('Prova1');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes)
SELECT
  'WP_000462905',
  'P0A6R3',
  'global DNA-binding transcriptional dual regulator [Escherichia coli str. K-12 substr. MG1655].',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('Prova1') LIMIT 1),
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='P0A6R3'
);

UPDATE core_tfinstance
SET
  TF_id = (SELECT TF_id FROM core_tf WHERE lower(name)=lower('Prova1') LIMIT 1),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_000462905'),
  description = 'global DNA-binding transcriptional dual regulator [Escherichia coli str. K-12 substr. MG1655].',
  notes = COALESCE(notes, '')
WHERE uniprot_accession='P0A6R3';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Staphylococcus aureus subsp. aureus COL', 'Staphylococcus aureus subsp. aureus COL', NULL,
   0, NULL, 'Revision reason: Other reason (specify in notes)
Prova rao',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='P0A6R3' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='P0A6R3' LIMIT 1)
);

