INSERT INTO core_taxonomy (taxonomy_id, rank, name, parent_id)
SELECT
  '93062',
  'strain',
  'Staphylococcus aureus subsp. aureus COL',
  NULL
WHERE NOT EXISTS (
  SELECT 1 FROM core_taxonomy WHERE taxonomy_id='93062'
);

UPDATE core_taxonomy
SET
  rank = COALESCE(NULLIF(rank,''), 'strain'),
  name = COALESCE(NULLIF(name,''), 'Staphylococcus aureus subsp. aureus COL'),
  parent_id = COALESCE(parent_id, NULL)
WHERE taxonomy_id='93062';

UPDATE core_genome
SET taxonomy_id = (
  SELECT id FROM core_taxonomy WHERE taxonomy_id='93062' LIMIT 1
)
WHERE genome_accession='NC_002951.2';

INSERT INTO core_experimentaltechnique (name, description, preset_function, EO_term)
SELECT 'ChIP-PCR', 'ChIP-PCR', NULL, 'ECO:0005620'
WHERE NOT EXISTS (
  SELECT 1 FROM core_experimentaltechnique WHERE EO_term='ECO:0005620'
);

INSERT INTO core_siteinstance (_seq, genome_id, start, end, strand)
SELECT
  'AAAAAAAAA',
  (SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1),
  1334104,
  1334112,
  1
WHERE NOT EXISTS (
  SELECT 1 FROM core_siteinstance
  WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
    AND start=1334104 AND end=1334112 AND strand=1
    AND _seq='AAAAAAAAA'
);

INSERT INTO core_curation_siteinstance
  (curation_id, site_instance_id, annotated_seq, quantitative_value, site_type, TF_function, TF_type)
VALUES
  ((SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1),
   (SELECT site_id FROM core_siteinstance
        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
          AND start=1334104 AND end=1334112 AND strand=1
          AND _seq='AAAAAAAAA'
        ORDER BY site_id DESC LIMIT 1),
   'AAAAAAAAA',
   0,
   'variable',
   'dual',
   'monomer');

INSERT INTO core_curation_siteinstance_experimental_techniques
  (curation_siteinstance_id, experimentaltechnique_id)
SELECT (SELECT id FROM core_curation_siteinstance
        WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1)
          AND site_instance_id=(SELECT site_id FROM core_siteinstance
        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
          AND start=1334104 AND end=1334112 AND strand=1
          AND _seq='AAAAAAAAA'
        ORDER BY site_id DESC LIMIT 1)
        ORDER BY id DESC LIMIT 1), (SELECT technique_id
          FROM core_experimentaltechnique
          WHERE EO_term='ECO:0005620'
          LIMIT 1)
WHERE (SELECT technique_id
          FROM core_experimentaltechnique
          WHERE EO_term='ECO:0005620'
          LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM core_curation_siteinstance_experimental_techniques
    WHERE curation_siteinstance_id=(SELECT id FROM core_curation_siteinstance
        WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1)
          AND site_instance_id=(SELECT site_id FROM core_siteinstance
        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
          AND start=1334104 AND end=1334112 AND strand=1
          AND _seq='AAAAAAAAA'
        ORDER BY site_id DESC LIMIT 1)
        ORDER BY id DESC LIMIT 1)
      AND experimentaltechnique_id=(SELECT technique_id
          FROM core_experimentaltechnique
          WHERE EO_term='ECO:0005620'
          LIMIT 1)
  );

INSERT INTO core_regulation (curation_site_instance_id, gene_id, evidence_type, meta_site_id)
SELECT
  (SELECT id FROM core_curation_siteinstance
        WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37045140' LIMIT 1) ORDER BY curation_id DESC LIMIT 1)
          AND site_instance_id=(SELECT site_id FROM core_siteinstance
        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
          AND start=1334104 AND end=1334112 AND strand=1
          AND _seq='AAAAAAAAA'
        ORDER BY site_id DESC LIMIT 1)
        ORDER BY id DESC LIMIT 1),
  (SELECT gene_id FROM core_gene
            WHERE locus_tag='SACOL_RS06710' AND genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
            ORDER BY gene_id DESC LIMIT 1),
  'exp_verified',
  NULL
WHERE (SELECT gene_id FROM core_gene
            WHERE locus_tag='SACOL_RS06710' AND genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_002951.2' LIMIT 1)
            ORDER BY gene_id DESC LIMIT 1) IS NOT NULL;

